    this.chunkM = r.i('chunk_m');
    this.speedMps = new TuningSpeedMps(r.sub('speed_mps'));
    this.roads = new TuningRoads(r.sub('roads'));
    this.buildings = new TuningBuildings(r.sub('buildings'));
